                    "通讯终止。使用标准终止信号（「那我先走了」「回头聊」）并执行告别仪式——可能包含挥手（单手左右摆动 2–4 次，频率约 2Hz）、点头、口头祝福等复合动作。两个中国人之间的告别通常需要 2–3 轮拉锯（「别送了」「送送吧」「真的别送了」「就送到门口」），请提前为告别仪式分配充足时间预算。",
