                "按说明清洗可拆部件和内筒，擦拭门封褶皱与外壳。需要运行筒清洁程序时使用合规清洁剂，并保持空间通风。",
                "冲净残留、擦干门封并保持舱门微开，接通水电后进行短时空载测试。记录清洁日期和异常噪声，为后续维修提供信息。",
                "不要在通电、进水状态下把手伸进设备内部。洗衣机漏电、漏水或剧烈晃动时应停止使用并通知专业人员。",
