                "拆下可清洗滤网，清除灰尘并充分晾干；擦拭出风口和外壳，避免液体进入电路。高处或内部深度清洁交给专业人员。",
                "装回干燥滤网，恢复电源并测试风量、异味和漏水情况。清理地面与工具，记录下一次维护时间。",
                "湿滤网和带电清洁会造成电气风险。闻到焦味、发现制冷剂异味或漏水时，不要继续拆机。",
