                "按标签选择手洗、机洗或干洗，处理局部污渍时从不显眼区域测试。清洗过程中保持窗帘与尖锐挂件分离。",
                "充分脱水或轻压吸水后按要求晾干，再按原顺序挂回并检查轨道运行。收起梯具和清洁用品，恢复窗边通道。",
                "湿重窗帘可能超过轨道承重，也不应在未固定的高处直接拆挂。褪色、缩水或霉变严重时应交给专业清洁节点。",
