                "加入清水后轻轻搅动并倒出浑水，按食材需要重复数次。动作不要过猛，以免米粒随水流大量流失。",
                "按烹饪比例加入最终用水，检查内胆外壁干燥后放入电饭锅或锅具。清理台面与水槽，保存未用米粒。",
                "淘米水不是默认可饮用液体，也不要让内胆外壁带水接触电器加热部件。发现米粒霉味或虫蛀时停止使用。",
