                "加热至水沸腾后保持合适火力，过程中不要频繁掀盖。需要检查时先关火、侧向揭盖，让蒸汽远离面部和手臂。",
                "确认食物中心达到可食用状态，关闭热源并用夹具取出容器。倒掉或冷却剩水，清洗蒸锅并擦干。",
                "蒸汽温度高且可在瞬间造成烫伤。不要把脸贴近锅盖，也不要让锅内水烧干后继续运行。",
