                "水沸腾后逐步下入面条并搅散，维持不会溢出的火力。按包装时间结合口感测试，避免把锅底和面条交给无人监控。",
                "关火后沥水或连汤盛出，加入调味和配料。关闭热源、清理溢出的淀粉水并把锅具移到安全位置。",
                "沸水和蒸汽会让面条烹饪区成为高温区域。锅面起泡上涌时不要猛然把脸靠近，也不要用冷水直接冲热锅。",
