                "以小火持续加热并定期搅动，观察沸腾高度和锅底粘附情况。需要离开时使用安全定时器，不要让慢煮任务无限期运行。",
                "达到稠度后关闭热源并静置，盛出时避开热蒸汽。清洗锅具和勺子，处理溢锅痕迹，保存剩余粥品。",
                "粥会突然沸腾溢出，且高温液体黏附皮肤后更难甩开。锅具不可过满，搅动时保持身体远离锅沿。",
