                "先加热锅具再按顺序下油、下料，保持翻炒动作短而可控。生熟食材分阶段处理，观察颜色、气味和火力变化。",
                "确认食材熟透后关火盛出，避免锅具余温继续过度加热。擦去油点、清洗工具并确认灶台没有残留火焰。",
                "水分进入高温油会造成飞溅，锅内起火时不要泼水。闻到焦味或油烟异常时应降低火力、通风并按安全方式处理。",
