                "按顺序混合、打发、整形并装入模具，控制搅拌程度与面糊厚度。预热完成后戴隔热手套放入烤箱，按时间观察颜色和膨胀。",
                "出炉后放置在耐热支撑面冷却，再脱模、切分和保存。关闭烤箱、清理溅出的面糊与器具，记录配方调整。",
