                "按距离、温度和时间控制烘烤，过程中观察焦化速度和油脂滴落。需要翻面时关闭或降低热源，使用长柄工具。",
                "达到熟度后先关闭热源再取出，放在耐热面冷却。清理烤盘与油污，确认设备内部没有遗留食物和可燃物。",
