                "将鸡蛋在独立容器中打开后倒入锅内，保持低到中火让蛋白逐步凝固。按需要翻面或加盖，确认蛋清和蛋黄达到目标熟度。",
                "关火后用铲子取出，盛入干净盘具并清理锅面油点。洗手、清洗锅具，处理破损蛋壳。",
