                "加热至沸腾后按目标熟度计时，必要时降低火力防止碰撞破裂。取出时使用勺子或夹具，避免徒手接触沸水。",
                "放入冷水降温并剥壳，检查内部熟度和气味。未立即食用的鸡蛋擦干、标记时间并冷藏。",
