                "少量加入并充分混合，等待片刻再试味。根据咸、甜、酸、辣和鲜度分步调整，不要一次倾倒大量调味品来跳过反馈循环。",
                "达到目标后盖紧容器，记录成功比例并把勺子清洗。若味道过重，使用增加菜量或稀释等方式补救，不要继续叠加新的刺激。",
