                "先闻气味，再小口感知咸淡、酸甜、辣度和熟度。让样品稍微降温，避免用大口吞咽替代测试。",
                "根据结果调整火力、调味或继续加热，样勺清洗后再用。完成菜品前进行最后一次独立采样，确认没有异物或异常气味。",
