                "按常用顺序将餐具放在每个座位附近，保持边缘对齐和取用距离合理。刀刃朝内、筷子平稳，热菜器皿留出防烫空间。",
                "放置调味品、纸巾和公用餐具，确认通道没有被椅子和餐具堵住。用餐结束后按分类回收，保持桌面可清理。",
