                "把餐具、菜品和纸巾放在可触及但不拥挤的位置，公用菜靠近中心，个人碗盘保持足够空间。必要时使用隔热垫。",
                "从每个座位观察一次，确认没有挡住通道、门口或他人视线。用餐前处理溢出的液体，用餐后按顺序撤下餐具。",
