                "从容器两侧或托盘中心抬起，沿缓慢、短距离路线移动。转弯和放下前先提醒附近人类，避免把热气和汤汁突然送到对方身边。",
                "将菜品放在稳定桌面中央，撤回手后再调整位置。检查容器外壁是否滴漏，清理路线上的汤汁并把托盘归位。",
