                "使用公用餐具按份量取出，先照顾有明确限制或需要较早进食的个体。动作从容，避免把个人餐具伸入公共菜盘。",
                "分餐后将工具放回指定位置，检查每份数量和温度。剩余食物及时覆盖、标记并保存，清理掉落物。",
