                "按一次食用量分装，减少反复开合和重复加热。盖紧容器并标注名称、制作时间和建议食用期限，放入冰箱合适区域。",
                "冷藏或冷冻后按先入先出取用，食用前执行外观、气味和保存时间检查。容器空出后清洗、晾干并检查密封圈。",
